function stepsToExit(maze: string[][], entrance: number[]): number {
  const R = maze.length, C = maze[0].length;
  const dist = maze.map(row => row.map(() => Infinity));
  dist[entrance[0]][entrance[1]] = 0;
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  let changed = true;
  while (changed) {
    changed = false;
    for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {
      if (maze[r][c] !== ".") continue;
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr < 0 || nc < 0 || nr >= R || nc >= C) continue;
        if (dist[nr][nc] + 1 < dist[r][c]) { dist[r][c] = dist[nr][nc] + 1; changed = true; }
      }
    }
  }
  let best = Infinity;
  for (let r = 0; r < R; r++) for (let c = 0; c < C; c++) {
    const border = r === 0 || c === 0 || r === R - 1 || c === C - 1;
    if (border && maze[r][c] === "." && dist[r][c] > 0) best = Math.min(best, dist[r][c]);
  }
  return best === Infinity ? -1 : best;
}

