    def stepsToExit(self, maze: List[List[str]], entrance: List[int]) -> int:
        R, C = len(maze), len(maze[0])
        INF = float("inf")
        dist = [[INF] * C for _ in range(R)]
        dist[entrance[0]][entrance[1]] = 0
        changed = True
        while changed:
            changed = False
            for r in range(R):
                for c in range(C):
                    if maze[r][c] != ".":
                        continue
                    for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
