function stepsToExit(maze: string[][], entrance: number[]): number {
  const R = maze.length, C = maze[0].length;
  const seen = maze.map(row => row.map(() => false));
  const [sr, sc] = entrance;
  seen[sr][sc] = true;
  let frontier: number[][] = [[sr, sc]];
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  for (let steps = 1; frontier.length; steps++) {
    const next: number[][] = [];
    for (const [r, c] of frontier) {
      for (const [dr, dc] of dirs) {
        const nr = r + dr, nc = c + dc;
        if (nr < 0 || nc < 0 || nr >= R || nc >= C) continue;
        if (maze[nr][nc] !== "." || seen[nr][nc]) continue;
        if (nr === 0 || nc === 0 || nr === R - 1 || nc === C - 1) return steps;
        seen[nr][nc] = true;
        next.push([nr, nc]);
      }
    }
    frontier = next;
  }
  return -1;
}

